import csv
ids = {
 'cool': '3ec6613e-4d87-5159-ac83-7852e7c94984',
 'heat': '73f7a82c-2e72-5d4e-90c0-8e6bbf10cc51',
 'temp': 'be41bf6b-c1ca-5cc0-a271-2cd4fca56654',
}
data = {k: {} for k in ids}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row["timeseries_id"] in ids.values():
            key = [k for k,v in ids.items() if v==row["timeseries_id"]][0]
            ts = row["timestamp"]
            if ts.startswith("2018-07-16"):
                data[key][ts] = float(row["value"])

for k in data:
    print(k, len(data[k]))
# combine
allts = sorted(set(data['temp']) | set(data['cool']) | set(data['heat']))
count = 0
for ts in allts:
    t = data['temp'].get(ts)
    c = data['cool'].get(ts)
    h = data['heat'].get(ts)
    out = False
    if t is not None and ( (h is not None and t < h) or (c is not None and t > c) ):
        out = True
    count += 1 if out else 0
    print(ts, t, h, c, out)
print("COUNT", count)
